<section class="panel"><div class="panel-head"><div><span class="panel-kicker">سجل التحرير</span><h2>نسخ المقال السابقة</h2></div><a class="btn btn-ghost" href="/writer/articles/<?=$article['id']?>">العودة للمقال</a></div><?php if(!$rows):?><div class="empty-state"><strong>لا توجد نسخ محفوظة بعد</strong><p>تُنشأ نسخة عند تغيير محتوى المقال.</p></div><?php else:?><div class="revision-list"><?php foreach($rows as $r):$cur=$current[$r['locale']]??null;?><article class="revision-card revision-card-compare"><div class="revision-meta"><strong><?=e(language_flag($r['locale']).' '.language_name($r['locale']))?></strong><small><?=e($r['editor_name'])?> · <?=e($r['created_at'])?></small></div><div class="revision-compare-grid"><div><span>النسخة المحفوظة</span><h3><?=e($r['title']??'')?></h3><p><?=e(mb_substr(trim(strip_tags((string)($r['content']??''))),0,300))?>…</p></div><div><span>النسخة الحالية</span><h3><?=e($cur['title']??'—')?></h3><p><?=e(mb_substr(trim(strip_tags((string)($cur['content']??''))),0,300))?>…</p></div></div><form method="post" action="/admin/articles/revisions/restore" onsubmit="return confirm('استعادة هذه النسخة؟ سيتم استبدال المحتوى الحالي لهذه اللغة.')"><?=csrf_field()?><input type="hidden" name="revision_id" value="<?=$r['id']?>"><button class="btn btn-primary">استعادة هذه النسخة</button></form></article><?php endforeach;?></div><?php endif;?></section>
